function Shiksha(){
    return(
    <div className="h-[670px] mx-[100px] rounded-[28px]" 
	style={{
		background: "linear-gradient(180deg, #0066B2, #002B4C)"
	}}>
        <img
	src={"https://storage.googleapis.com/tagjs-prod.appspot.com/v1/9w1KRIs84F/e6z0htik_expires_30_days.png"} 
	className="w-[500px] h-[500px] object-fill"
/>
<img
	src={"https://storage.googleapis.com/tagjs-prod.appspot.com/v1/9w1KRIs84F/1qsqzcod_expires_30_days.png"} 
	className="w-[500px] h-[500px] object-fill"
/>
</div>
    );
}
export default Shiksha;
